INSERT INTO public.classification_standards (level, node_key, title_ar, title_en, summary_ar, summary_en, requirements, sources, status, review_note) VALUES
  ('activity', $v$K:المصرفية للأفراد والشركات$v$, $v$معيار نشاط المصرفية للأفراد والشركات$v$, $v$Standard for retail and corporate banking$v$, $v$يضبط الإقراض والإيداع وصيغ التمويل في المصارف، زائدًا على معيار صناعة المالية والاستثمار.$v$, $v$Governs lending, deposits and financing structures in banks, in addition to the finance and investment industry standard.$v$, $v$[{"kind":"prohibition","ar":"الإقراض والإيداع بفائدة؛ فالقرض عقد إرفاق لا معاوضة، وكل قرضٍ جرّ نفعًا مشروطًا فهو ربا.","en":"Lending or taking deposits at interest; a loan is an act of benevolence, not exchange, and any loan that brings a stipulated benefit is riba.","ref":"AAOIFI المعيار الشرعي 19 (القرض)"},{"kind":"mandatory","ar":"التمويل بالصيغ المشروعة: المرابحة للآمر بالشراء، والإجارة المنتهية بالتمليك، والمشاركة المتناقصة، والاستصناع.","en":"Finance through lawful structures: murabahah to the purchase orderer, ijarah ending in ownership, diminishing musharakah, and istisna'.","ref":"AAOIFI المعايير الشرعية 8 و9 و11 و12"},{"kind":"mandatory","ar":"تملّك المصرف للسلعة وقبضها قبضًا حقيقيًّا أو حكميًّا معتبرًا قبل بيعها مرابحة.","en":"The bank must own the goods and take real or valid constructive possession before selling them by murabahah.","ref":"AAOIFI المعيار الشرعي 18 (القبض)"},{"kind":"prohibition","ar":"بيع العِينة، والتورّق المنظّم الذي لا حقيقة للسلعة فيه، وغرامات التأخير التي تعود للمصرف ربحًا.","en":"'Inah sales, organised tawarruq with no real commodity, and late-payment charges retained by the bank as profit.","ref":"AAOIFI المعياران الشرعيان 3 و30"},{"kind":"mandatory","ar":"هيئة رقابة شرعية مستقلة، وتدقيق شرعي دوري، وتطهير الإيراد غير المباح وصرفه في وجوه الخير دون أن ينتفع به المصرف.","en":"An independent Shariah board, periodic Shariah audit, and purification of non-permissible income given to charity without benefit to the bank.","ref":"معايير الحوكمة لأيوفي"}]$v$::jsonb, $v$["AAOIFI المعايير الشرعية 3 و8 و9 و11 و12 و18 و19 و30"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$K:الصكوك$v$, $v$معيار نشاط الصكوك$v$, $v$Standard for sukuk$v$, $v$يضبط هيكلة الصكوك وإصدارها وتداولها.$v$, $v$Governs the structuring, issuance and trading of sukuk.$v$, $v$[{"kind":"mandatory","ar":"أن يمثّل الصك حصة شائعة في أعيان أو منافع أو خدمات أو موجودات مشروع، لا دينًا في ذمة المُصدِر.","en":"A sukuk certificate must represent an undivided share in assets, usufruct, services or project assets, not a debt owed by the issuer.","ref":"AAOIFI المعيار الشرعي 17 (صكوك الاستثمار)"},{"kind":"prohibition","ar":"ضمان المُصدِر أو المدير لرأس المال أو لعائد ثابت؛ فحملة الصكوك يتحملون الغنم والغرم بحسب ملكيتهم.","en":"The issuer or manager guaranteeing capital or a fixed return; holders share profit and loss according to ownership.","ref":"AAOIFI المعيار الشرعي 17"},{"kind":"condition","ar":"تداول صكوك المرابحة والسلم بعد التنضيض أو صيرورة موجوداتها ديونًا لا يجوز إلا بضوابط تداول الدين والصرف.","en":"Murabahah and salam sukuk whose assets have become debts may only be traded under the rules on debt and currency exchange.","ref":"AAOIFI المعيار الشرعي 17"},{"kind":"condition","ar":"يجوز تعهّد المدير بالشراء بالقيمة السوقية أو بثمن يُتفق عليه عند الشراء، لا بالقيمة الاسمية.","en":"A manager's purchase undertaking is permitted at market value or a price agreed at the time of purchase, not at par.","ref":"AAOIFI المعيار الشرعي 17"},{"kind":"mandatory","ar":"الإفصاح في نشرة الإصدار عن الهيكل والموجودات والمخاطر ورأي الهيئة الشرعية.","en":"Disclose the structure, assets, risks and the Shariah board's opinion in the prospectus.","ref":"مبدأ الشفافية"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 17 (صكوك الاستثمار)"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$K:التمويل الأصغر$v$, $v$معيار نشاط التمويل الأصغر$v$, $v$Standard for microfinance$v$, $v$يضبط التمويل الأصغر والتنموي بما يحقق التمكين ويمنع استغلال الحاجة.$v$, $v$Governs micro and development finance to empower borrowers and prevent exploiting need.$v$, $v$[{"kind":"prohibition","ar":"الزيادة على القرض الحسن بأي اسم، ولو سُمّيت رسمًا أو عمولة مرتبطة بمبلغ القرض أو مدته.","en":"Any increase on a benevolent loan under any name, even if called a fee or commission linked to the loan amount or term.","ref":"AAOIFI المعيار الشرعي 19 (القرض)"},{"kind":"condition","ar":"تجوز أجرة الخدمة الفعلية المقطوعة بقدر التكلفة، دون ربطها بمقدار القرض.","en":"A flat fee for actual service at cost is permitted, not linked to the loan amount.","ref":"قرار مجمع الفقه الإسلامي في أجور خدمات القروض"},{"kind":"condition","ar":"التمويل الإنتاجي بالمشاركة والمضاربة والمرابحة والسلم بحسب طبيعة المشروع.","en":"Productive finance through musharakah, mudarabah, murabahah or salam according to the project.","ref":"AAOIFI المعايير الشرعية 8 و10 و12 و13"},{"kind":"mandatory","ar":"مراعاة مقصد التمكين: تقييم القدرة على السداد، وإنظار المعسر، ومنع أساليب التحصيل المهينة.","en":"Serve empowerment: assess repayment capacity, grant respite to those in hardship, and avoid humiliating collection.","ref":"قوله تعالى: ﴿وإن كان ذو عسرةٍ فنظرةٌ إلى ميسرة﴾"},{"kind":"condition","ar":"ما يُلتزم به عند المماطلة من تبرّع يُصرف في الخير ولا يعود للمموّل.","en":"Any charitable undertaking on default goes to charity, not to the financier.","ref":"AAOIFI المعيار الشرعي 3"}]$v$::jsonb, $v$["AAOIFI المعايير الشرعية 3 و8 و10 و12 و13 و19"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$K:إدارة الأصول والصناديق$v$, $v$معيار نشاط إدارة الأصول والصناديق$v$, $v$Standard for asset and fund management$v$, $v$يضبط إدارة الصناديق والمحافظ الاستثمارية.$v$, $v$Governs investment funds and portfolio management.$v$, $v$[{"kind":"mandatory","ar":"حصر الاستثمار في الأنشطة المباحة، وتطبيق الفرز الشرعي على الأسهم.","en":"Invest only in permissible activities and apply Shariah screening to equities.","ref":"AAOIFI المعيار الشرعي 21"},{"kind":"mandatory","ar":"فصل أموال الصندوق عن أموال المدير، والتصرف بعقد وكالة بأجر أو مضاربة.","en":"Segregate fund assets from the manager's, acting under paid agency or mudarabah.","ref":"AAOIFI المعياران الشرعيان 13 و23"},{"kind":"prohibition","ar":"ضمان المدير لرأس المال أو الربح إلا عند التعدي أو التقصير أو مخالفة الشروط.","en":"The manager guaranteeing capital or profit, except for transgression, negligence or breach of terms.","ref":"أحكام الأمانة"},{"kind":"mandatory","ar":"تطهير الإيراد غير المباح دوريًّا والإفصاح عن نسبته للمستثمرين.","en":"Purify non-permissible income periodically and disclose its ratio to investors.","ref":"AAOIFI المعيار الشرعي 21"},{"kind":"condition","ar":"الإفصاح عن الرسوم وهيكلها، وشروط الاكتتاب والاسترداد بما ينفي الغرر.","en":"Disclose fees and their structure, and subscription and redemption terms, so as to remove gharar.","ref":"النهي عن الغرر"}]$v$::jsonb, $v$["AAOIFI المعايير الشرعية 13 و21 و23"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$K:البورصات$v$, $v$معيار نشاط البورصات والتداول$v$, $v$Standard for stock exchanges and trading$v$, $v$يضبط تداول الأوراق المالية في الأسواق المنظمة.$v$, $v$Governs trading of securities on organised markets.$v$, $v$[{"kind":"condition","ar":"يجوز تداول أسهم الشركات المباحة؛ فالسهم حصة شائعة في موجودات الشركة، مع تطبيق حدود الفرز والتطهير.","en":"Trading shares of permissible companies is allowed, as a share is an undivided interest in company assets, subject to screens and purification.","ref":"AAOIFI المعيار الشرعي 21"},{"kind":"prohibition","ar":"البيع على المكشوف، والتداول بالهامش القائم على قرض ربوي، وإقراض الأسهم بعوض.","en":"Short selling, margin trading funded by interest-bearing loans, and lending shares for a fee.","ref":"AAOIFI المعيار الشرعي 21"},{"kind":"prohibition","ar":"المشتقات القائمة على الغرر والمراهنة كالخيارات والمستقبليات المجرّدة.","en":"Derivatives built on gharar and wagering, such as conventional options and futures.","ref":"AAOIFI المعيار الشرعي 20"},{"kind":"prohibition","ar":"النجش، والتلاعب بالأسعار، والتداول بناءً على معلومات داخلية.","en":"Price manipulation (najsh) and insider trading.","ref":"النهي عن النجش والغش"},{"kind":"condition","ar":"المؤشرات الإسلامية: بناؤها على معايير فرز معلنة ومراجعة دورية.","en":"Islamic indices must use published screening criteria with periodic review.","ref":"AAOIFI المعيار الشرعي 27 (المؤشرات)"}]$v$::jsonb, $v$["AAOIFI المعايير الشرعية 20 و21 و27"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$K:المدفوعات الرقمية$v$, $v$معيار نشاط المدفوعات الرقمية$v$, $v$Standard for digital payments$v$, $v$يضبط المحافظ الرقمية والتحويلات وبوابات الدفع.$v$, $v$Governs digital wallets, transfers and payment gateways.$v$, $v$[{"kind":"condition","ar":"تجوز الأجرة على خدمة التحويل والتحصيل (إجارة أو جعالة) دون ربطها بمبلغٍ على وجه القرض.","en":"Fees for transfer and collection services (hire or ju'alah) are permitted, not tied to an amount as a loan charge.","ref":"أحكام الإجارة والجعالة"},{"kind":"mandatory","ar":"أحكام الصرف عند تبادل العملات: التقابض ولو حكميًّا بالقيد الفوري، والتماثل عند اتحاد الجنس.","en":"Currency exchange rules: hand-to-hand exchange, including constructive possession by instant booking, and equality when currencies are the same.","ref":"AAOIFI المعيار الشرعي 1 (المتاجرة في العملات)"},{"kind":"condition","ar":"أرصدة المحافظ الرقمية قروض مضمونة للعميل؛ فلا يُمنح عليها عائد مشروط، ويُستثمر المصدر ما يأذن به النظام في المباح.","en":"Wallet balances are guaranteed loans to the provider; no stipulated return may be paid on them, and any permitted investment must be in lawful assets.","ref":"AAOIFI المعيار الشرعي 19 (القرض)"},{"kind":"prohibition","ar":"تمكين المدفوعات لمواقع القمار والإباحية والإقراض الربوي.","en":"Processing payments for gambling, pornography or interest-based lending.","ref":"النهي عن الإعانة على الإثم"},{"kind":"mandatory","ar":"أمن البيانات وخصوصية المستخدم وحفظ الأمانة.","en":"Data security, user privacy and safeguarding trust.","ref":"أحكام الأمانة"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 1","AAOIFI المعيار الشرعي 19"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$K:التمويل الجماعي$v$, $v$معيار نشاط التمويل الجماعي$v$, $v$Standard for crowdfunding$v$, $v$يضبط منصات التمويل الجماعي بالمشاركة والتبرع والمكافأة.$v$, $v$Governs equity, donation and reward crowdfunding platforms.$v$, $v$[{"kind":"condition","ar":"التمويل بالمشاركة والمضاربة: تحديد الحصص، وقسمة الربح نسبةً شائعة، وتحمّل الخسارة بقدر رأس المال.","en":"Musharakah and mudarabah crowdfunding: defined shares, profit split as a proportion, and losses borne by capital.","ref":"AAOIFI المعياران الشرعيان 12 و13"},{"kind":"prohibition","ar":"التمويل الإقراضي بفائدة ولو صغرت النسبة أو سُمّيت رسمًا.","en":"Interest-bearing lending, however small the rate or whatever it is called.","ref":"تحريم الربا"},{"kind":"condition","ar":"نموذجا التبرع والمكافأة جائزان بشرط الشفافية، وانتفاء الغرر الفاحش في المكافأة، والصرف في المُعلَن.","en":"Donation and reward models are permitted with transparency, no gross gharar in rewards, and spending as announced.","ref":"أحكام الهبة والوعد"},{"kind":"mandatory","ar":"فحص المنصة لمشروعية المشروعات المعروضة، والإفصاح عن المخاطر وعمولتها.","en":"The platform vets projects for permissibility and discloses risks and its commission.","ref":"AAOIFI المعيار الشرعي 23 (الوكالة)"}]$v$::jsonb, $v$["AAOIFI المعايير الشرعية 12 و13 و23"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$K:العملات والأصول المشفّرة$v$, $v$معيار نشاط العملات والأصول المشفّرة$v$, $v$Standard for cryptocurrencies and crypto-assets$v$, $v$نشاطٌ في وضع «قيد الدراسة / إحالة» بمخاطر شرعية مرتفعة، إلى أن تصدر الهيئة قرارًا.$v$, $v$An activity "under study / referral" with high Shariah risk until the board rules.$v$, $v$[{"kind":"condition","ar":"وضع إحالة بمخاطر S3 فأعلى: قرار مجمع الفقه الإسلامي الدولي 237 (8/24) أوصى بمزيد الدراسة ولم يصدر حكمًا قاطعًا.","en":"Referral status at S3 risk or higher: International Islamic Fiqh Academy resolution 237 (8/24) called for further study without a final ruling.","ref":"قرار مجمع الفقه 237 (8/24)"},{"kind":"prohibition","ar":"ما فيه قمارٌ أو مراهنة أو جهالة فاحشة، كالمشتقات بالرافعة والتداول بالهامش الربوي.","en":"Anything involving gambling, wagering or gross uncertainty, such as leveraged derivatives and interest-funded margin trading.","ref":"تحريم الميسر والغرر"},{"kind":"condition","ar":"ترميز أصلٍ حقيقي مملوك أقرب إلى الجواز، والعبرة بالأصل المرمَّز لا بالتقنية.","en":"Tokenising a real, owned asset is closer to permissibility; what matters is the underlying asset, not the technology.","ref":"قاعدة «العبرة بالمقاصد والمعاني»"},{"kind":"mandatory","ar":"عرض كل منتج أو خدمة على هيئة شرعية مؤهلة قبل الإطلاق، وتصنيفها «قيد الدراسة» حتى يصدر القرار.","en":"Submit every product or service to a qualified Shariah board before launch, classified \"under study\" until it rules.","ref":"الحالات الخاصة في المعيار"}]$v$::jsonb, $v$["قرار مجمع الفقه الإسلامي الدولي 237"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$K:التكافل$v$, $v$معيار نشاط التكافل$v$, $v$Standard for takaful$v$, $v$يضبط التأمين التكافلي القائم على التبرع.$v$, $v$Governs donation-based takaful insurance.$v$, $v$[{"kind":"mandatory","ar":"قيام العقد على التبرع أو الالتزام بالتبرع، لا على المعاوضة الاحتمالية.","en":"The contract rests on donation or a commitment to donate, not an aleatory exchange.","ref":"AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)"},{"kind":"mandatory","ar":"فصل صندوق المشتركين عن أموال الشركة المديرة، وأجرة المدير وكالةً أو حصة مضاربة معلومة.","en":"Separate the participants' fund from the operator's assets; the operator earns a known agency fee or mudarabah share.","ref":"AAOIFI المعيار الشرعي 26"},{"kind":"mandatory","ar":"استثمار أموال التكافل في المباح فقط.","en":"Invest takaful funds only in permissible assets.","ref":"AAOIFI المعيار الشرعي 21"},{"kind":"condition","ar":"توزيع الفائض التأميني على المشتركين وفق اللائحة، ويقدّم المدير قرضًا حسنًا عند العجز.","en":"Distribute underwriting surplus to participants per the rules; the operator provides a benevolent loan in deficit.","ref":"AAOIFI المعيار الشرعي 26"},{"kind":"condition","ar":"إعادة التكافل مع جهات متوافقة، وتُقبل إعادة التأمين التقليدي للحاجة بضوابط الهيئة.","en":"Retakaful with compliant providers; conventional reinsurance is accepted only of need under board rules.","ref":"AAOIFI المعيار الشرعي 41 (إعادة التأمين)"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 21","AAOIFI المعيار الشرعي 26"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$A:زراعة الحبوب$v$, $v$معيار نشاط زراعة الحبوب$v$, $v$Standard for cereal farming$v$, $v$يضبط زراعة الحبوب وبيعها وزكاتها.$v$, $v$Governs growing, selling and paying zakat on cereals.$v$, $v$[{"kind":"mandatory","ar":"زكاة الحبوب: نصابها خمسة أوسق، والعشر فيما سُقي بلا مؤونة ونصفه فيما سُقي بمؤونة.","en":"Zakat on grain: nisab of five awsuq; a tenth when rain-fed and a twentieth when irrigated at cost.","ref":"AAOIFI المعيار الشرعي 35"},{"kind":"condition","ar":"السلم في الحبوب موصوفةً في الذمة جائز بشروطه.","en":"Salam in grain described as a liability is permitted on its conditions.","ref":"AAOIFI المعيار الشرعي 10"},{"kind":"prohibition","ar":"بيع الحب قبل اشتداده على التبقية.","en":"Selling grain before it hardens on condition that it stays in the field.","ref":"النهي عن بيع الحب حتى يشتد"},{"kind":"mandatory","ar":"الصدق في الكيل والجودة، ومنع الاحتكار في أقوات الناس.","en":"Honest measures and quality, and no hoarding of staple food.","ref":"حديث «لا يحتكر إلا خاطئ»"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 10","AAOIFI المعيار الشرعي 35"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$A:زراعة الفاكهة$v$, $v$معيار نشاط زراعة الفاكهة$v$, $v$Standard for fruit farming$v$, $v$يضبط بيع الثمار والمساقاة وزكاة الثمار.$v$, $v$Governs fruit sales, musaqah and zakat on fruit.$v$, $v$[{"kind":"prohibition","ar":"بيع الثمار قبل بدوّ صلاحها إلا بشرط القطع.","en":"Selling fruit before it ripens, unless on condition of immediate picking.","ref":"النهي عن بيع الثمار حتى يبدو صلاحها"},{"kind":"condition","ar":"بدوّ الصلاح ظهور النضج وأمن العاهة، ويختلف باختلاف الثمر.","en":"Ripening means signs of maturity and safety from blight, varying by fruit.","ref":"كتب الفقه في بيع الثمار"},{"kind":"mandatory","ar":"زكاة الثمار الزكوية كالتمر والزبيب: العشر أو نصفه بعد بلوغ النصاب، ويُحال غيرها إلى منهجية الهيئة لاختلاف المذاهب.","en":"Zakat on zakatable fruit such as dates and raisins: a tenth or a twentieth above nisab; other fruit follows the board's methodology given differences among schools.","ref":"AAOIFI المعيار الشرعي 35"},{"kind":"condition","ar":"المساقاة بجزء شائع معلوم من الثمر.","en":"Musaqah for a known undivided share of the fruit.","ref":"معاملة خيبر"},{"kind":"mandatory","ar":"منع الغش في الوزن والجودة وكتمان العيب.","en":"No fraud in weight or quality, and no concealment of defects.","ref":"حديث «من غشّنا فليس منّا»"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 35"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$A:تربية الأبقار$v$, $v$معيار نشاط تربية الأبقار$v$, $v$Standard for cattle farming$v$, $v$يضبط تربية الأبقار وزكاتها وذبحها.$v$, $v$Governs rearing, zakat and slaughter of cattle.$v$, $v$[{"kind":"condition","ar":"زكاة السائمة: تجب في البقر السائمة الحول إذا بلغت النصاب (في كل ثلاثين تبيع). والمعلوفة المعدّة للتجارة تُزكّى زكاة عروض التجارة، وتُحال التفاصيل إلى منهجية الهيئة.","en":"Zakat on grazing cattle: due on cattle grazing for a year at nisab (a yearling per thirty). Fodder-fed cattle held for trade pay trade-goods zakat; details follow the board's methodology.","ref":"AAOIFI المعيار الشرعي 35"},{"kind":"mandatory","ar":"الرفق بالحيوان وحسن الملكة، وتحريم تعذيبه أو تجويعه.","en":"Kindness and good care of animals; no torture or starvation.","ref":"حديث «إن الله كتب الإحسان على كل شيء»"},{"kind":"mandatory","ar":"طيب العلف وخلوّه من المحرّم والنجس، وحبس الجلّالة حتى يطيب لحمها.","en":"Wholesome feed free of prohibited and impure matter; jallalah animals are confined until their meat is wholesome.","ref":"أحكام الجلّالة"},{"kind":"mandatory","ar":"الذكاة الشرعية: أهلية الذابح، والتسمية، وإنهار الدم بقطع الحلقوم والمريء.","en":"Shariah slaughter: a qualified slaughterer, invoking God's name, and letting blood by cutting the windpipe and oesophagus.","ref":"OIC/SMIIC 1"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 35","OIC/SMIIC 1"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$A:مزارع الدواجن$v$, $v$معيار نشاط مزارع الدواجن$v$, $v$Standard for poultry farming$v$, $v$يضبط إنتاج الدواجن وذبحها وتسويقها.$v$, $v$Governs poultry production, slaughter and marketing.$v$, $v$[{"kind":"mandatory","ar":"طيب العلف وخلوّه من الميتة والنجاسات.","en":"Wholesome feed free of carrion and impurities.","ref":"أحكام الجلّالة"},{"kind":"mandatory","ar":"الذكاة الشرعية شرطٌ لحلّ اللحم، مع التسمية وإحسان الذبح.","en":"Shariah slaughter is required for the meat to be lawful, with God's name invoked and humane slaughter.","ref":"OIC/SMIIC 1"},{"kind":"condition","ar":"الصعق قبل الذبح: يُقبل فقط بما لا يُميت الطير قبل الذبح، وفق ضوابط الهيئة ومعيار الحلال المعتمد.","en":"Pre-slaughter stunning is accepted only if it does not kill the bird before slaughter, per board rules and the adopted halal standard.","ref":"OIC/SMIIC 1"},{"kind":"mandatory","ar":"الصدق في الوصف والتاريخ والوزن، وضمان السلامة الصحية للمستهلك.","en":"Truthful description, dates and weights, and consumer health safety.","ref":"مقصد حفظ النفس"}]$v$::jsonb, $v$["OIC/SMIIC 1"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$A:الاستزراع السمكي$v$, $v$معيار نشاط الاستزراع السمكي$v$, $v$Standard for aquaculture$v$, $v$يضبط استزراع الأسماك وتغذيتها وبيعها.$v$, $v$Governs fish farming, feeding and sale.$v$, $v$[{"kind":"condition","ar":"السمك حلال بأصل الشرع وميتته حلال، ولا تشترط له ذكاة.","en":"Fish are lawful in principle, including when found dead, and need no slaughter.","ref":"حديث «هو الطهور ماؤه الحلّ ميتته»"},{"kind":"mandatory","ar":"طيب العلف، وما أُطعم النجاسة يُحبس حتى يطيب.","en":"Wholesome feed; fish fed on impurities are held until wholesome.","ref":"أحكام الجلّالة"},{"kind":"mandatory","ar":"عدم الإضرار بالبيئة المائية والجوار بالمخلّفات والأمراض.","en":"No harm to the aquatic environment or neighbours through waste or disease.","ref":"قاعدة «لا ضرر ولا ضرار»"},{"kind":"condition","ar":"السلم في الأسماك موصوفةً في الذمة إلى أجل معلوم جائز.","en":"Salam in fish described as a liability to a known date is permitted.","ref":"AAOIFI المعيار الشرعي 10"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 10"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$A:إنتاج العسل$v$, $v$معيار نشاط إنتاج العسل$v$, $v$Standard for honey production$v$, $v$يضبط إنتاج العسل وتسويقه وزكاته.$v$, $v$Governs honey production, marketing and zakat.$v$, $v$[{"kind":"condition","ar":"زكاة العسل محل خلاف: أوجبها الحنفية والحنابلة إذا بلغ النصاب، ولم يوجبها المالكية والشافعية. تُحال إلى منهجية الهيئة.","en":"Zakat on honey is disputed: Hanafis and Hanbalis require it above nisab, Malikis and Shafi'is do not. Referred to the board's methodology.","ref":"AAOIFI المعيار الشرعي 35"},{"kind":"prohibition","ar":"غش العسل بخلطه بالسكر أو المحليات مع كتمان ذلك.","en":"Adulterating honey with sugar or sweeteners while concealing it.","ref":"حديث «من غشّنا فليس منّا»"},{"kind":"mandatory","ar":"الصدق في وصف المصدر والنوع، والرفق بالنحل وعدم إتلافه بلا حاجة.","en":"Truthful description of source and type, and care for bees without needless destruction.","ref":"النهي عن الغش والإفساد"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 35"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$A:الصيد البحري$v$, $v$معيار نشاط الصيد البحري$v$, $v$Standard for marine fishing$v$, $v$يضبط الصيد البحري والمحافظة على الثروة السمكية.$v$, $v$Governs marine fishing and conservation of fish stocks.$v$, $v$[{"kind":"condition","ar":"صيد البحر حلال ولا يحتاج إلى ذكاة.","en":"Seafood is lawful and needs no slaughter.","ref":"قوله تعالى: ﴿أُحلّ لكم صيد البحر وطعامه﴾"},{"kind":"prohibition","ar":"الصيد في المناطق والمواسم المحظورة نظامًا للحماية، والصيد الجائر المدمّر للمخزون.","en":"Fishing in areas or seasons closed for protection, and destructive overfishing.","ref":"قاعدة «لا ضرر ولا ضرار»"},{"kind":"mandatory","ar":"الصدق في وصف الصيد ونوعه وتاريخ صيده.","en":"Truthful description of the catch, species and catch date.","ref":"النهي عن الغش"}]$v$::jsonb, $v$["أحكام الصيد في كتب الفقه"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$A:قطع الأخشاب$v$, $v$معيار نشاط قطع الأخشاب$v$, $v$Standard for logging$v$, $v$يضبط قطع الأشجار والانتفاع بالغابات.$v$, $v$Governs tree felling and forest use.$v$, $v$[{"kind":"mandatory","ar":"أن يكون القطع من شجر مملوك أو مأذون فيه، دون اعتداء على الملك العام أو المحميات.","en":"Fell only owned or licensed trees, without encroaching on public land or reserves.","ref":"أحكام الملك العام"},{"kind":"prohibition","ar":"قطع الشجر المثمر أو ما فيه نفع عام لغير حاجة.","en":"Felling fruit-bearing trees or trees of public benefit without need.","ref":"النهي عن الإفساد في الأرض"},{"kind":"recommended","ar":"إعادة التشجير والاستدامة حفظًا للمال والنفس.","en":"Reforestation and sustainability to preserve wealth and life.","ref":"حديث «إن قامت الساعة وفي يد أحدكم فسيلة فليغرسها»"},{"kind":"mandatory","ar":"الوفاء بعقود التوريد ومواصفاتها.","en":"Honour supply contracts and their specifications.","ref":"قوله تعالى: ﴿أوفوا بالعقود﴾"}]$v$::jsonb, $v$["أحكام الملك العام والإحياء"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$C:تصنيع اللحوم والأسماك$v$, $v$معيار نشاط تصنيع اللحوم والأسماك$v$, $v$Standard for meat and fish processing$v$, $v$يضبط الذبح والتصنيع والتغليف للحوم والأسماك.$v$, $v$Governs slaughter, processing and packaging of meat and fish.$v$, $v$[{"kind":"mandatory","ar":"الذكاة الشرعية: أهلية الذابح (مسلم أو كتابي)، والتسمية، وقطع الحلقوم والمريء وإنهار الدم.","en":"Shariah slaughter: a qualified slaughterer (Muslim or of the People of the Book), invoking God's name, and cutting the windpipe and oesophagus to let blood.","ref":"OIC/SMIIC 1"},{"kind":"prohibition","ar":"ما ذُبح على غير اسم الله أو مات خنقًا أو صعقًا قبل الذبح فهو ميتة.","en":"Anything slaughtered in other than God's name, or killed by strangling or stunning before slaughter, is carrion.","ref":"قوله تعالى: ﴿حُرّمت عليكم الميتة…﴾"},{"kind":"mandatory","ar":"فصل خطوط الإنتاج الحلال ومنع التلوث المتبادل، وخلو المضافات والأغلفة من المحرّم.","en":"Separate halal lines and prevent cross-contamination, with additives and casings free of prohibited matter.","ref":"OIC/SMIIC 1"},{"kind":"condition","ar":"اللحوم المستزرعة مخبريًا: تُقبل بالشروط التي قررها مجمع الفقه في قراره 265، وتحال تفاصيلها إلى الهيئة.","en":"Cultivated meat is accepted on the conditions set by fiqh academy resolution 265, with details referred to the board.","ref":"قرار مجمع الفقه 265"},{"kind":"mandatory","ar":"الصدق في الوسم والتاريخ وبلد المنشأ وشهادة الحلال.","en":"Truthful labelling, dates, origin and halal certification.","ref":"OIC/SMIIC 1"}]$v$::jsonb, $v$["OIC/SMIIC 1","قرار مجمع الفقه الإسلامي الدولي 265"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$C:تصنيع الأدوية$v$, $v$معيار نشاط تصنيع الأدوية$v$, $v$Standard for pharmaceutical manufacturing$v$, $v$يضبط مكوّنات الأدوية وجودتها وتسعيرها.$v$, $v$Governs pharmaceutical ingredients, quality and pricing.$v$, $v$[{"kind":"condition","ar":"الأصل التداوي بالمباح، ولا يُستعمل المحرّم إلا لضرورة مع انتفاء البديل.","en":"Treatment with lawful substances is the rule; prohibited ones are used only of necessity without alternatives.","ref":"قاعدة «الضرورات تبيح المحظورات»"},{"kind":"condition","ar":"الاستحالة: ما تغيّرت حقيقته فالجمهور على طهارته وحِلّه، ويضيّقها الشافعية. تعتمد الهيئة المذهب المعمول به.","en":"Transformation: most jurists deem a fully transformed substance pure and lawful, while Shafi'is restrict this. The board sets the approach followed.","ref":"قرارات مجمع الفقه في الاستحالة"},{"kind":"mandatory","ar":"الإفصاح عن المكوّنات ذات الأصل المحرّم (كالكحول والجيلاتين) ونسبتها.","en":"Disclose ingredients of prohibited origin (such as alcohol and gelatin) and their proportion.","ref":"معايير SMIIC للدواء الحلال"},{"kind":"prohibition","ar":"الغش في الجودة، واحتكار الأدوية الضرورية أو المغالاة فيها.","en":"Quality fraud, and hoarding or overpricing essential medicines.","ref":"حديث «لا يحتكر إلا خاطئ»"}]$v$::jsonb, $v$["معايير SMIIC للدواء الحلال","قرارات مجمع الفقه الإسلامي الدولي"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$C:مستحضرات التجميل$v$, $v$معيار نشاط مستحضرات التجميل$v$, $v$Standard for cosmetics$v$, $v$يضبط مكوّنات مستحضرات التجميل وتسويقها.$v$, $v$Governs cosmetic ingredients and marketing.$v$, $v$[{"kind":"condition","ar":"الأصل إباحة الزينة المباحة، ويحرم ما فيه تغيير لخلق الله كالوشم.","en":"Lawful adornment is permitted; altering God's creation, such as tattooing, is not.","ref":"حديث لعن الواشمة"},{"kind":"mandatory","ar":"خلوّ المكوّنات من النجس والمحرّم كالشحوم غير المذكّاة والكحول المسكر.","en":"Ingredients free of impure or prohibited matter, such as fats from unslaughtered animals and intoxicating alcohol.","ref":"OIC/SMIIC 4"},{"kind":"mandatory","ar":"السلامة وعدم الإضرار بالبدن، فحفظ النفس مقدّم على الزينة.","en":"Safety and no bodily harm, since preserving life precedes adornment.","ref":"مقصد حفظ النفس"},{"kind":"mandatory","ar":"الصدق في الوصف والدعاية.","en":"Truthful descriptions and advertising.","ref":"النهي عن الغش"}]$v$::jsonb, $v$["OIC/SMIIC 4 (مستحضرات التجميل الحلال)"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$C:صناعة الملابس$v$, $v$معيار نشاط صناعة الملابس$v$, $v$Standard for apparel manufacturing$v$, $v$يضبط تصنيع الملابس وخاماتها وحقوق العاملين فيها.$v$, $v$Governs apparel production, materials and workers' rights.$v$, $v$[{"kind":"condition","ar":"الأصل الإباحة. وتصنيع الحرير الطبيعي والذهب جائز لإباحتهما للنساء، ويُمنع ما يُصمَّم أصالةً للبس المحرّم.","en":"Permissible in principle. Natural silk and gold may be produced since they are lawful for women; items designed mainly for prohibited wear are not.","ref":"حديث «أُحلّ الذهب والحرير لإناث أمتي»"},{"kind":"prohibition","ar":"الشعارات المحرّمة أو الداعية إلى المحرّم على الملابس.","en":"Prohibited slogans or symbols promoting the prohibited on garments.","ref":"النهي عن الإعانة على الإثم"},{"kind":"mandatory","ar":"حقوق العاملين: أجر عادل وسلامة مهنية ومنع عمل الأطفال الضار.","en":"Workers' rights: fair pay, occupational safety, and no harmful child labour.","ref":"حديث «أعطوا الأجير أجره»"},{"kind":"mandatory","ar":"الصدق في الخامات والمقاسات وبلد المنشأ.","en":"Truthful materials, sizes and country of origin.","ref":"النهي عن الغش"}]$v$::jsonb, $v$["أحكام اللباس في كتب الفقه"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$C:المخابز$v$, $v$معيار نشاط المخابز$v$, $v$Standard for bakeries$v$, $v$يضبط صناعة الخبز والمعجنات وتسعيرها.$v$, $v$Governs bread and pastry production and pricing.$v$, $v$[{"kind":"mandatory","ar":"طيب المدخلات وخلوّها من المحرّم كدهن الخنزير والكحول والجيلاتين غير المذكّى.","en":"Wholesome inputs free of prohibited ingredients such as lard, alcohol and non-halal gelatin.","ref":"OIC/SMIIC 1"},{"kind":"prohibition","ar":"الغش في الوزن والجودة، واحتكار أقوات الناس.","en":"Fraud in weight or quality, and hoarding staple food.","ref":"حديث «لا يحتكر إلا خاطئ»"},{"kind":"condition","ar":"الالتزام بالتسعير الذي يفرضه وليّ الأمر للمصلحة العامة ما لم يكن فيه ظلم.","en":"Comply with price controls set for the public interest unless unjust.","ref":"أحكام التسعير"},{"kind":"mandatory","ar":"النظافة والسلامة الصحية.","en":"Hygiene and food safety.","ref":"مقصد حفظ النفس"}]$v$::jsonb, $v$["OIC/SMIIC 1"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
