  ('activity', $v$S2:المنصّات الخيرية الرقمية$v$, $v$معيار نشاط المنصات الخيرية الرقمية$v$, $v$Standard for digital charity platforms$v$, $v$يضبط جمع التبرعات عبر المنصات الرقمية.$v$, $v$Governs fundraising through digital platforms.$v$, $v$[{"kind":"mandatory","ar":"أموال التبرع أمانة لا تُخلط بمال المنصة.","en":"Donations are a trust, not mixed with the platform's funds.","ref":"أحكام الأمانة"},{"kind":"prohibition","ar":"الكذب في وصف الحالات والتغرير العاطفي.","en":"Misrepresenting cases or emotional manipulation.","ref":"النهي عن الغش"},{"kind":"condition","ar":"تجوز أجرة معلومة على الخدمة مع الإفصاح للمتبرع. ولا تؤخذ من الزكاة إلا في حدود سهم العاملين عليها وفق ضوابط الهيئة.","en":"A known service fee is permitted with disclosure; it may be taken from zakat only within the administrators' share under board rules.","ref":"مصرف «العاملين عليها»"},{"kind":"mandatory","ar":"الإفصاح عن نسب التحصيل ومآل الأموال.","en":"Disclose collection ratios and where funds go.","ref":"مبدأ الشفافية"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 35"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$S2:الحج والعمرة$v$, $v$معيار نشاط خدمات الحج والعمرة$v$, $v$Standard for Hajj and Umrah services$v$, $v$يضبط تنظيم رحلات الحج والعمرة.$v$, $v$Governs organising Hajj and Umrah trips.$v$, $v$[{"kind":"mandatory","ar":"الالتزام بالتصاريح والأنظمة المنظِّمة درءًا للزحام والضرر.","en":"Comply with permits and regulations to prevent crowding and harm.","ref":"طاعة وليّ الأمر في المعروف"},{"kind":"mandatory","ar":"الأمانة في وصف السكن والإعاشة والنقل، والضمان عند التقصير.","en":"Honest description of lodging, catering and transport, with liability for shortfalls.","ref":"أحكام الإجارة والضمان"},{"kind":"prohibition","ar":"استغلال الحاجة بالمغالاة في المواسم.","en":"Exploiting need through seasonal overpricing.","ref":"النهي عن الظلم"},{"kind":"mandatory","ar":"إعانة الحاج على أداء نسكه وعدم تفويت واجباته بسوء التنظيم، مع مرشدين مؤهلين.","en":"Help pilgrims complete their rites without missing obligations through poor organisation, with qualified guides.","ref":"أحكام المناسك"}]$v$::jsonb, $v$["أحكام الحج والعمرة"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$S2:إدارة المساجد$v$, $v$معيار نشاط إدارة المساجد$v$, $v$Standard for mosque management$v$, $v$يضبط إدارة المساجد وأوقافها.$v$, $v$Governs managing mosques and their endowments.$v$, $v$[{"kind":"mandatory","ar":"المسجد وقف لله لا يُصرف عن جهته.","en":"A mosque is an endowment to God and may not be diverted from its purpose.","ref":"AAOIFI المعيار الشرعي 33"},{"kind":"prohibition","ar":"البيع والشراء وإنشاد الضالة داخل المسجد.","en":"Buying, selling or announcing lost property inside the mosque.","ref":"حديث النهي عن البيع في المسجد"},{"kind":"mandatory","ar":"تقديم الأهلية في الإمامة، وأمانة الناظر في التبرعات والأوقاف.","en":"Appoint qualified imams, with the administrator a trustee of donations and endowments.","ref":"حديث «يؤمّ القوم أقرؤهم لكتاب الله»"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 33"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$J:الذكاء الاصطناعي$v$, $v$معيار نشاط الذكاء الاصطناعي$v$, $v$Standard for artificial intelligence$v$, $v$يضبط تطوير أنظمة الذكاء الاصطناعي وتشغيلها.$v$, $v$Governs developing and operating AI systems.$v$, $v$[{"kind":"prohibition","ar":"استعماله في التزوير والغش وانتهاك الخصوصية والمحتوى الفاحش.","en":"Using it for forgery, fraud, privacy violations or indecent content.","ref":"النهي عن الإعانة على الإثم"},{"kind":"mandatory","ar":"الأتمتة تُعين ولا تُفتي؛ فالاجتهاد للهيئات الشرعية البشرية ولا يُفوَّض للآلة.","en":"Automation assists but never issues fatwas; ijtihad belongs to human Shariah boards and is not delegated to machines.","ref":"ضوابط الفتوى"},{"kind":"mandatory","ar":"الأمانة في البيانات ومصادرها وحقوق الملكية الفكرية.","en":"Integrity of data and its sources, and respect for intellectual property.","ref":"قرار مجمع الفقه بشأن الحقوق المعنوية"},{"kind":"mandatory","ar":"الإفصاح عن كون المحتوى مولّدًا آليًّا؛ فكتمانه تغرير.","en":"Disclose that content is machine-generated; concealing it is deception.","ref":"النهي عن التغرير"},{"kind":"condition","ar":"ضمان الضرر يرجع إلى المشغّل والمطوّر بحسب التعدي والتقصير.","en":"Liability for harm rests with the operator and developer according to transgression and negligence.","ref":"أحكام الضمان"}]$v$::jsonb, $v$["قرارات مجمع الفقه الإسلامي الدولي"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$J:الأمن السيبراني$v$, $v$معيار نشاط الأمن السيبراني$v$, $v$Standard for cybersecurity$v$, $v$يضبط خدمات الحماية واختبار الاختراق.$v$, $v$Governs protection services and penetration testing.$v$, $v$[{"kind":"condition","ar":"اختبار الاختراق الأخلاقي جائز بإذن صريح من المالك وفي حدود المتفق عليه.","en":"Ethical penetration testing is permitted with the owner's explicit consent and within the agreed scope.","ref":"أحكام الإذن"},{"kind":"prohibition","ar":"الاختراق والتجسس وكشف الخصوصيات دون إذن.","en":"Hacking, spying or exposing private data without permission.","ref":"قوله تعالى: ﴿ولا تجسّسوا﴾"},{"kind":"prohibition","ar":"استغلال الثغرات المكتشفة أو بيعها لمن يضر.","en":"Exploiting discovered vulnerabilities or selling them to those who would cause harm.","ref":"النهي عن الإعانة على الإثم"},{"kind":"mandatory","ar":"الوفاء بعقود السرية وحفظ الأسرار.","en":"Honour confidentiality agreements and keep secrets.","ref":"أحكام الأمانة"}]$v$::jsonb, $v$["أحكام الأمانة والإذن"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('activity', $v$J:تطوير الألعاب الإلكترونية$v$, $v$معيار نشاط تطوير الألعاب الإلكترونية$v$, $v$Standard for video game development$v$, $v$يضبط تصميم الألعاب ونماذج إيرادها.$v$, $v$Governs game design and revenue models.$v$, $v$[{"kind":"condition","ar":"الأصل إباحة اللهو المباح ما لم يشغل عن واجب.","en":"Lawful entertainment is permitted unless it distracts from obligations.","ref":"أحكام اللهو المباح"},{"kind":"prohibition","ar":"الميسر والمراهنة على المال، ومنها صناديق الغنائم المدفوعة.","en":"Gambling and wagering money, including paid loot boxes.","ref":"تحريم الميسر"},{"kind":"prohibition","ar":"الصور الفاحشة، والمحتوى المخالف للعقيدة أو المحرّض على المحرّم.","en":"Indecent imagery, and content contrary to creed or inciting the prohibited.","ref":"النهي عن الإعانة على الإثم"},{"kind":"mandatory","ar":"الإفصاح عن المشتريات داخل اللعبة، وحماية الأطفال من الاستغلال.","en":"Disclose in-game purchases and protect children from exploitation.","ref":"مقصد حفظ العقل والمال"}]$v$::jsonb, $v$["أحكام الميسر واللهو في كتب الفقه"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$)
